/*
 * vram_cap: a drop-in libcuda.so.1 that forwards every CUDA driver call to the real library but
 * returns CUDA_ERROR_OUT_OF_MEMORY once the process's device memory would pass VRAM_CAP_BYTES.
 * Gives TEI (which has no allocator limit of its own) a cap like PyTorch's per-process fraction.
 * Counts non-pool allocations plus the current memory pool's reserved size; allocations made by the
 * driver itself are not counted (the NVML device total covers them). Unintercepted exports go
 * through trampolines generated by gen_trampolines.py.
 * Env: VRAM_CAP_BYTES (0 or unset = count only), VRAM_CAP_REAL_LIBCUDA, VRAM_CAP_REPORT (JSON
 * status file), VRAM_CAP_VERBOSE=1.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <glob.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "trampolines.h"

typedef int CUresult;
typedef int CUdevice;
typedef unsigned long long CUdeviceptr;
typedef unsigned int CUdeviceptr_v1;
typedef void *CUstream;
typedef void *CUmemoryPool;
typedef int CUmemPool_attribute;
typedef unsigned long long CUmemGenericAllocationHandle;
typedef unsigned long long cuuint64_t;
#define CUDA_SUCCESS 0
#define CUDA_ERROR_OUT_OF_MEMORY 2
#define CUDA_ERROR_NOT_INITIALIZED 3
#define CU_MEMPOOL_ATTR_RESERVED_MEM_CURRENT 5
#define CU_MEMPOOL_ATTR_RESERVED_MEM_HIGH 6
#define CU_MEMPOOL_ATTR_USED_MEM_CURRENT 7
#define CU_MEMPOOL_ATTR_USED_MEM_HIGH 8

#define KIND_NONPOOL 1
#define KIND_POOL 2

__attribute__((visibility("hidden"))) void *vram_cap_real_table[VRAM_CAP_N_TRAMPOLINES];

static void *real_lib;
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static size_t cap_bytes = 0;
static size_t used_bytes = 0;          /* live bytes of all tracked allocations (logical) */
static size_t nonpool_used = 0;        /* live bytes of non-pool allocations */
static size_t pool_used_counter = 0;   /* live bytes of pooled allocations (own accounting) */
static size_t peak_bytes = 0;          /* peak of used_bytes */
static size_t peak_physical = 0;       /* peak of nonpool_used + pool reserved */
static size_t max_overshoot = 0;       /* largest transient excursion of a refused pool attempt */
static size_t pool_reserved_last = 0, pool_used_last = 0, pool_reserved_high_last = 0, pool_used_high_last = 0;
static int pool_known = 0;
static unsigned long n_alloc_calls = 0;
static unsigned long n_free_calls = 0;
static unsigned long n_refusals = 0;
static unsigned long n_overshoot_refusals = 0;
static unsigned long n_real_failures = 0;
static int verbose = 0;
static volatile int exiting = 0;
static const char *report_path = NULL;
static char last_refusal[400] = "";
static char real_path[512] = "";
static int trampolines_missing = 0;

/* ---- live allocation table: linear probing with backward-shift deletion ---- */
#define TABLE_BITS 17
#define TABLE_SIZE (1u << TABLE_BITS)
static struct {
    uint64_t key;
    uint64_t size;
    uint8_t live;
    uint8_t kind;
} table[TABLE_SIZE];
static size_t table_live = 0;
static int table_overflow = 0;

static uint32_t hash_key(uint64_t k) {
    k ^= k >> 33;
    k *= 0xff51afd7ed558ccdULL;
    k ^= k >> 33;
    k *= 0xc4ceb9fe1a85ec53ULL;
    k ^= k >> 33;
    return (uint32_t)k & (TABLE_SIZE - 1);
}

static void table_put(uint64_t key, uint64_t size, uint8_t kind) {
    if (table_live >= TABLE_SIZE - 2) {
        table_overflow = 1;
        return;
    }
    uint32_t i = hash_key(key);
    while (table[i].live) {
        if (table[i].key == key) {
            table[i].size = size;
            table[i].kind = kind;
            return;
        }
        i = (i + 1) & (TABLE_SIZE - 1);
    }
    table[i].key = key;
    table[i].size = size;
    table[i].kind = kind;
    table[i].live = 1;
    table_live++;
}

static int cyc_between(uint32_t h, uint32_t j, uint32_t k) { /* j in [h, k) cyclically */
    if (h <= k) return h <= j && j < k;
    return j >= h || j < k;
}

static int table_take(uint64_t key, uint64_t *size, uint8_t *kind) {
    uint32_t i = hash_key(key);
    while (table[i].live) {
        if (table[i].key == key) {
            *size = table[i].size;
            *kind = table[i].kind;
            uint32_t j = i, k = (i + 1) & (TABLE_SIZE - 1);
            while (table[k].live) {
                uint32_t h = hash_key(table[k].key);
                if (cyc_between(h, j, k)) {
                    table[j] = table[k];
                    j = k;
                }
                k = (k + 1) & (TABLE_SIZE - 1);
            }
            table[j].live = 0;
            table_live--;
            return 1;
        }
        i = (i + 1) & (TABLE_SIZE - 1);
    }
    return 0;
}

