/* Pointers handed out by the real cuGetProcAddress (versioned variants chosen by the driver). */
static alloc_fn gpa_cuMemAlloc;
static alloc_async_fn gpa_cuMemAllocAsync;
static alloc_pool_fn gpa_cuMemAllocFromPoolAsync;
static alloc_pitch_fn gpa_cuMemAllocPitch;
static alloc_managed_fn gpa_cuMemAllocManaged;
static mem_create_fn gpa_cuMemCreate;
static mem_release_fn gpa_cuMemRelease;
static free_fn gpa_cuMemFree;
static free_async_fn gpa_cuMemFreeAsync;
static get_info_fn gpa_cuMemGetInfo;

/* ---- the device's memory pool ---- */
static CUmemoryPool device_pool = NULL;

/* The device's current memory pool. Before a context exists the driver answers CUDA_SUCCESS with
 * a NULL pool, so the lookup is simply repeated on later calls until a pool is returned. */
static CUmemoryPool get_pool(void) {
    if (device_pool) return device_pool;
    CUmemoryPool p = NULL;
    if (real_cuDeviceGetMemPool && real_cuDeviceGetMemPool(&p, 0) == CUDA_SUCCESS && p) {
        device_pool = p;
    } else if (real_cuDeviceGetDefaultMemPool && real_cuDeviceGetDefaultMemPool(&p, 0) == CUDA_SUCCESS && p) {
        device_pool = p;
    }
    if (device_pool) {
        pool_known = 1;
        if (verbose) fprintf(stderr, "[vram_cap] device memory pool %p\n", device_pool);
    }
    return device_pool;
}

/* Refreshes the cached pool statistics from the driver; returns 1 on success. Lock held. */
static int query_pool(void) {
    if (exiting) return 0;
    CUmemoryPool p = get_pool();
    if (!p || !real_cuMemPoolGetAttribute) return 0;
    cuuint64_t r = 0, u = 0, rh = 0, uh = 0;
    if (real_cuMemPoolGetAttribute(p, CU_MEMPOOL_ATTR_RESERVED_MEM_CURRENT, &r) != CUDA_SUCCESS) return 0;
    if (real_cuMemPoolGetAttribute(p, CU_MEMPOOL_ATTR_USED_MEM_CURRENT, &u) != CUDA_SUCCESS) return 0;
    real_cuMemPoolGetAttribute(p, CU_MEMPOOL_ATTR_RESERVED_MEM_HIGH, &rh);
    real_cuMemPoolGetAttribute(p, CU_MEMPOOL_ATTR_USED_MEM_HIGH, &uh);
    pool_reserved_last = (size_t)r;
    pool_used_last = (size_t)u;
    pool_reserved_high_last = (size_t)rh;
    pool_used_high_last = (size_t)uh;
    return 1;
}

/* Physical device memory of the tracked allocations: non-pool live bytes + pool reserved bytes
 * (falls back to the own pool counter when the pool cannot be queried). Lock held. */
static size_t physical_now(void) {
    size_t phys = query_pool() ? nonpool_used + pool_reserved_last : nonpool_used + pool_used_counter;
    if (phys > peak_physical) peak_physical = phys;
    return phys;
}

/* ---- reporting ---- */
static double now_s(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
}

static void write_report_locked(const char *event) {
    if (!report_path) return;
    char tmp[600];
    snprintf(tmp, sizeof tmp, "%s.tmp", report_path);
    FILE *f = fopen(tmp, "w");
    if (!f) return;
    fprintf(f,
            "{\"event\": \"%s\", \"time\": %.3f, \"cap_bytes\": %zu, \"used_bytes\": %zu, "
            "\"nonpool_used_bytes\": %zu, \"pool_used_counter_bytes\": %zu, \"pool_known\": %d, "
            "\"pool_used_bytes\": %zu, \"pool_reserved_bytes\": %zu, \"pool_reserved_high_bytes\": %zu, "
            "\"pool_used_high_bytes\": %zu, \"physical_bytes\": %zu, \"peak_bytes\": %zu, "
            "\"peak_physical_bytes\": %zu, \"max_overshoot_bytes\": %zu, \"n_alloc_calls\": %lu, "
            "\"n_free_calls\": %lu, \"n_refusals\": %lu, \"n_overshoot_refusals\": %lu, "
            "\"n_real_failures\": %lu, \"live_allocations\": %zu, \"table_overflow\": %d, "
            "\"trampolines\": %d, \"trampolines_missing\": %d, \"real_libcuda\": \"%s\", "
            "\"last_refusal\": \"%s\"}\n",
            event, now_s(), cap_bytes, used_bytes, nonpool_used, pool_used_counter, pool_known,
            pool_used_last, pool_reserved_last, pool_reserved_high_last, pool_used_high_last,
            nonpool_used + (pool_known ? pool_reserved_last : pool_used_counter), peak_bytes,
            peak_physical, max_overshoot, n_alloc_calls, n_free_calls, n_refusals,
            n_overshoot_refusals, n_real_failures, table_live, table_overflow,
            VRAM_CAP_N_TRAMPOLINES, trampolines_missing, real_path, last_refusal);
    fclose(f);
    rename(tmp, report_path);
}

static void refuse_locked(const char *fn, size_t bytes, size_t phys, const char *why) {
    n_refusals++;
    snprintf(last_refusal, sizeof last_refusal,
             "%s requested %zu bytes with %zu physical bytes (%zu live) against a cap of %zu bytes: %s",
             fn, bytes, phys, used_bytes, cap_bytes, why);
    fprintf(stderr, "[vram_cap] REFUSED %s bytes=%zu physical=%zu live=%zu cap=%zu (%s)\n", fn, bytes,
            phys, used_bytes, cap_bytes, why);
    write_report_locked("refusal");
}

/* ---- accounting: non-pool allocations (exact physical rule) ---- */
static int reserve_nonpool(const char *fn, size_t bytes) {
    pthread_mutex_lock(&lock);
    size_t phys = physical_now();
    if (cap_bytes && phys + bytes > cap_bytes) {
        refuse_locked(fn, bytes, phys, "non-pool allocation would pass the cap");
        pthread_mutex_unlock(&lock);
        return 0;
    }
    nonpool_used += bytes;
    used_bytes += bytes;
    if (used_bytes > peak_bytes) peak_bytes = used_bytes;
    if (nonpool_used + (pool_known ? pool_reserved_last : pool_used_counter) > peak_physical)
        peak_physical = nonpool_used + (pool_known ? pool_reserved_last : pool_used_counter);
    n_alloc_calls++;
    if (verbose) fprintf(stderr, "[vram_cap] %s bytes=%zu live=%zu physical=%zu\n", fn, bytes, used_bytes, phys + bytes);
    if ((n_alloc_calls & 63) == 0) write_report_locked("periodic");
    pthread_mutex_unlock(&lock);
    return 1;
}

static void settle_nonpool(const char *fn, CUresult r, uint64_t key, size_t bytes) {
    pthread_mutex_lock(&lock);
    if (r == CUDA_SUCCESS) {
        table_put(key, bytes, KIND_NONPOOL);
    } else {
        nonpool_used -= bytes;
        used_bytes -= bytes;
        n_real_failures++;
        fprintf(stderr, "[vram_cap] real %s failed with CUresult %d for %zu bytes\n", fn, r, bytes);
    }
    pthread_mutex_unlock(&lock);
}

/* ---- accounting: pool allocations (pre-check on used bytes, post-check on reserved bytes) ---- */
static int precheck_pool(const char *fn, size_t bytes) {
    pthread_mutex_lock(&lock);
    size_t phys = physical_now();
    size_t pool_used = pool_known ? pool_used_last : pool_used_counter;
    if (cap_bytes && nonpool_used + pool_used + bytes > cap_bytes) {
        refuse_locked(fn, bytes, phys, "pool allocation cannot fit: live bytes plus the request pass the cap");
        pthread_mutex_unlock(&lock);
        return 0;
    }
    n_alloc_calls++;
    if ((n_alloc_calls & 63) == 0) write_report_locked("periodic");
    pthread_mutex_unlock(&lock);
    return 1;
}

static CUresult postcheck_pool(const char *fn, CUresult r, CUdeviceptr *dptr, size_t bytes, CUstream stream,
                               CUmemoryPool pool_used_for_alloc) {
    if (r != CUDA_SUCCESS) {
        pthread_mutex_lock(&lock);
        n_real_failures++;
        fprintf(stderr, "[vram_cap] real %s failed with CUresult %d for %zu bytes\n", fn, r, bytes);
        pthread_mutex_unlock(&lock);
        return r;
    }
    pthread_mutex_lock(&lock);
    size_t phys = physical_now();
    if (cap_bytes && phys > cap_bytes) {
        size_t over = phys - cap_bytes;
        if (over > max_overshoot) max_overshoot = over;
        n_overshoot_refusals++;
        char why[160];
        snprintf(why, sizeof why, "the pool had to reserve new memory and its reserved size passed the cap by %zu bytes; the allocation was undone", over);
        refuse_locked(fn, bytes, phys, why);
        pthread_mutex_unlock(&lock);
        CUdeviceptr p = dptr ? *dptr : 0;
        if (p) {
            /* Nothing has been enqueued on the rejected block, so it can be freed on an idle
             * stream: the free completes at once, the trim then returns the newly reserved
             * chunk to the driver, and the excursion above the cap lasts milliseconds instead
             * of the busy stream's whole backlog. */
            if (!undo_stream && real_cuStreamCreate) real_cuStreamCreate(&undo_stream, 1 /* non-blocking */);
            CUstream s = undo_stream ? undo_stream : stream;
            if (real_cuMemFreeAsync) real_cuMemFreeAsync(p, s);
            if (real_cuStreamSynchronize) real_cuStreamSynchronize(s);
            CUmemoryPool pool = pool_used_for_alloc ? pool_used_for_alloc : get_pool();
            if (pool && real_cuMemPoolTrimTo) real_cuMemPoolTrimTo(pool, 0);
        }
        if (dptr) *dptr = 0;
        pthread_mutex_lock(&lock);
        physical_now();
        write_report_locked("refusal");
        pthread_mutex_unlock(&lock);
        return CUDA_ERROR_OUT_OF_MEMORY;
    }
    pool_used_counter += bytes;
    used_bytes += bytes;
    if (used_bytes > peak_bytes) peak_bytes = used_bytes;
    if (dptr) table_put((uint64_t)*dptr, bytes, KIND_POOL);
    if (verbose) fprintf(stderr, "[vram_cap] %s bytes=%zu live=%zu physical=%zu\n", fn, bytes, used_bytes, phys);
    pthread_mutex_unlock(&lock);
    return r;
}

static void release(const char *fn, uint64_t key) {
    uint64_t size = 0;
    uint8_t kind = 0;
    pthread_mutex_lock(&lock);
    n_free_calls++;
    if (table_take(key, &size, &kind)) {
        used_bytes -= size;
        if (kind == KIND_POOL) pool_used_counter -= size;
        else nonpool_used -= size;
        if (verbose)
            fprintf(stderr, "[vram_cap] %s bytes=%llu live=%zu\n", fn, (unsigned long long)size, used_bytes);
    } else if (verbose) {
        fprintf(stderr, "[vram_cap] %s of untracked pointer %llx\n", fn, (unsigned long long)key);
    }
    pthread_mutex_unlock(&lock);
}

/* ---- wrapper bodies ---- */
#define DEF_ALLOC(NAME, REALPTR)                                                             \
    CUresult NAME(CUdeviceptr *dptr, size_t bytesize) {                                      \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        if (!reserve_nonpool(#NAME, bytesize)) return CUDA_ERROR_OUT_OF_MEMORY;              \
        CUresult r = REALPTR(dptr, bytesize);                                                \
        settle_nonpool(#NAME, r, (r == CUDA_SUCCESS && dptr) ? (uint64_t)*dptr : 0, bytesize); \
        return r;                                                                            \
    }
#define DEF_ALLOC_ASYNC(NAME, REALPTR)                                                       \
    CUresult NAME(CUdeviceptr *dptr, size_t bytesize, CUstream stream) {                     \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        if (!precheck_pool(#NAME, bytesize)) return CUDA_ERROR_OUT_OF_MEMORY;                \
        CUresult r = REALPTR(dptr, bytesize, stream);                                        \
        return postcheck_pool(#NAME, r, dptr, bytesize, stream, NULL);                       \
    }
#define DEF_ALLOC_POOL(NAME, REALPTR)                                                        \
    CUresult NAME(CUdeviceptr *dptr, size_t bytesize, CUmemoryPool pool, CUstream stream) {  \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        if (!precheck_pool(#NAME, bytesize)) return CUDA_ERROR_OUT_OF_MEMORY;                \
        CUresult r = REALPTR(dptr, bytesize, pool, stream);                                  \
        return postcheck_pool(#NAME, r, dptr, bytesize, stream, pool);                       \
    }
#define DEF_ALLOC_MANAGED(NAME, REALPTR)                                                     \
    CUresult NAME(CUdeviceptr *dptr, size_t bytesize, unsigned int flags) {                  \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        if (!reserve_nonpool(#NAME, bytesize)) return CUDA_ERROR_OUT_OF_MEMORY;              \
        CUresult r = REALPTR(dptr, bytesize, flags);                                         \
        settle_nonpool(#NAME, r, (r == CUDA_SUCCESS && dptr) ? (uint64_t)*dptr : 0, bytesize); \
        return r;                                                                            \
    }
#define DEF_ALLOC_PITCH(NAME, REALPTR)                                                       \
    CUresult NAME(CUdeviceptr *dptr, size_t *pPitch, size_t width, size_t height,            \
                  unsigned int elem) {                                                       \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        size_t estimate = width * height;                                                    \
        if (!reserve_nonpool(#NAME, estimate)) return CUDA_ERROR_OUT_OF_MEMORY;              \
        CUresult r = REALPTR(dptr, pPitch, width, height, elem);                             \
        size_t actual = (r == CUDA_SUCCESS && pPitch) ? (*pPitch) * height : estimate;       \
        pthread_mutex_lock(&lock);                                                           \
        nonpool_used += actual - estimate;                                                   \
        used_bytes += actual - estimate;                                                     \
        if (used_bytes > peak_bytes) peak_bytes = used_bytes;                                \
        pthread_mutex_unlock(&lock);                                                         \
        settle_nonpool(#NAME, r, (r == CUDA_SUCCESS && dptr) ? (uint64_t)*dptr : 0, actual); \
        return r;                                                                            \
    }
#define DEF_MEM_CREATE(NAME, REALPTR)                                                        \
    CUresult NAME(CUmemGenericAllocationHandle *handle, size_t size, const void *prop,       \
                  unsigned long long flags) {                                                \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        if (!reserve_nonpool(#NAME, size)) return CUDA_ERROR_OUT_OF_MEMORY;                  \
        CUresult r = REALPTR(handle, size, prop, flags);                                     \
        settle_nonpool(#NAME, r, (r == CUDA_SUCCESS && handle) ? (uint64_t)*handle : 0, size); \
        return r;                                                                            \
    }
#define DEF_FREE(NAME, REALPTR)                                                              \
    CUresult NAME(CUdeviceptr dptr) {                                                        \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        CUresult r = REALPTR(dptr);                                                          \
        if (r == CUDA_SUCCESS) release(#NAME, (uint64_t)dptr);                               \
        return r;                                                                            \
    }
#define DEF_FREE_ASYNC(NAME, REALPTR)                                                        \
    CUresult NAME(CUdeviceptr dptr, CUstream stream) {                                       \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        CUresult r = REALPTR(dptr, stream);                                                  \
        if (r == CUDA_SUCCESS) release(#NAME, (uint64_t)dptr);                               \
        return r;                                                                            \
    }
#define DEF_MEM_RELEASE(NAME, REALPTR)                                                       \
    CUresult NAME(CUmemGenericAllocationHandle handle) {                                     \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        CUresult r = REALPTR(handle);                                                        \
        if (r == CUDA_SUCCESS) release(#NAME, (uint64_t)handle);                             \
        return r;                                                                            \
    }
#define DEF_GET_INFO(NAME, REALPTR)                                                          \
    CUresult NAME(size_t *free_out, size_t *total_out) {                                     \
        if (!REALPTR) return CUDA_ERROR_NOT_INITIALIZED;                                     \
        CUresult r = REALPTR(free_out, total_out);                                           \
        if (r == CUDA_SUCCESS && cap_bytes && free_out) {                                    \
            pthread_mutex_lock(&lock);                                                       \
            size_t phys = physical_now();                                                    \
            size_t remaining = cap_bytes > phys ? cap_bytes - phys : 0;                      \
            pthread_mutex_unlock(&lock);                                                     \
            if (*free_out > remaining) *free_out = remaining;                                \
        }                                                                                    \
        return r;                                                                            \
    }

